function showError(err){console.error(err);let msg=err?.message||'Terdapat masalah. Sila cuba lagi.';if(msg.includes('auth/operation-not-allowed'))msg='Aktifkan kaedah log masuk Email/Password dan Anonymous dalam Firebase Authentication.';if(msg.includes('PERMISSION_DENIED')||msg.includes('permission-denied')||msg.includes('storage/unauthorized'))msg='Kebenaran Firebase disekat. Pastikan Database Rules dan Storage Rules telah diterbitkan.';if(msg.includes('auth/invalid-credential'))msg='E-mel atau kata laluan tidak tepat.';toast(msg)}
