function guestHero(v){const cover=v.coverDisplay||v.coverUrl||'';return `<div class="sek-guest-portrait ${cover?'has-cover':''}" ${cover?`style="background-image:url('${e(cover)}');background-position:${Number(v.coverX)||50}% ${Number(v.coverY)||50}%;background-size:${Math.max(100,Number(v.coverZoom)||100)}% auto"`:''}><div class="sek-art-line"></div><div class="sek-portrait-caption"><div><b>${e(v.bride)} & ${e(v.groom)}</b><small>SEKEPING · HARI ISTIMEWA</small></div><div class="sek-photo-seal">S.</div></div></div>`}
